<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';import {formatMetric} from '../services/metrics';import {api,allPages,fmtDate,download} from '../services/api';import {usePage} from '../services/usePage';import Notice from '../components/Notice.vue';import StatusBadge from '../components/StatusBadge.vue';import EmptyState from '../components/EmptyState.vue';import {Line} from 'vue-chartjs';import {Chart as ChartJS,CategoryScale,LinearScale,PointElement,LineElement,Tooltip,Legend} from 'chart.js';ChartJS.register(CategoryScale,LinearScale,PointElement,LineElement,Tooltip,Legend)
const versions=ref<any[]>([]),runs=ref<any[]>([]),detail=ref<any>(null),artifacts=ref<string[]>([]),attempt=ref(1),form=ref({device:'server',version:'',architecture:'yolov8n.pt',epochs:50,batch:8,imgsz:640,lr0:.01,optimizer:'auto',weight_decay:.0005,patience:20,seed:42,fliplr:.5,degrees:10,hsv_v:.2});const {error,success,busy,act}=usePage();let timer:ReturnType<typeof setInterval>
async function files(){if(detail.value)artifacts.value=(await api.get(`training-runs/${detail.value.id}/artifacts/?attempt=${attempt.value}`)).data}
async function load(){runs.value=await allPages('training-runs/');if(detail.value){detail.value=runs.value.find(x=>x.id===detail.value.id);await files()}}
onMounted(()=>{act(async()=>{versions.value=await allPages('versions/');await load()});timer=setInterval(()=>{if(!busy.value)act(load)},8000)});onBeforeUnmount(()=>clearInterval(timer))
const submit=()=>act(async()=>{await api.post('training-runs/',form.value);await load()},'Entrenamiento registrado. El worker ejecutará el trabajo con el hardware configurado.')
const inspect=(run:any)=>act(async()=>{detail.value=run;attempt.value=Math.max(1,run.attempt);await files()})
</script>
<template><h1 class="heading">Entrena. Compara. Aprende.</h1><p class="subheading mb-7">Transferencia de aprendizaje con YOLOv8. Cada ejecución conserva su versión del dataset, parámetros y métricas.</p><Notice :error="error" :success="success"/><form @submit.prevent="submit" class="card mb-7"><div class="grid gap-4 md:grid-cols-3"><div><label class="label">Versión del dataset</label><select v-model="form.version" class="input" required><option value="">Selecciona una versión congelada</option><option v-for="v in versions" :key="v.id" :value="v.id">{{v.dataset_name}} · v{{v.number}} · {{v.count}} imágenes</option></select></div><div><label class="label">Modelo base preentrenado</label><select v-model="form.architecture" class="input"><option>yolov8n.pt</option><option>yolov8s.pt</option></select></div><div><label class="label">Resolución</label><select v-model.number="form.imgsz" class="input"><option :value="640">640</option><option :value="800">800</option></select></div></div><div class="mt-5 grid grid-cols-2 gap-4 md:grid-cols-4"><div v-for="field in (['epochs','batch','patience','seed'] as const)" :key="field"><label class="label">{{field}}</label><input v-model.number="form[field]" type="number" min="0" class="input" required/></div></div><details class="mt-5 rounded-xl bg-slate-50 p-4"><summary class="cursor-pointer text-sm font-medium">Optimización y aumento de datos</summary><div class="mt-4 grid grid-cols-2 gap-4 md:grid-cols-3"><div><label class="label">Optimizer</label><select v-model="form.optimizer" class="input"><option>auto</option><option>SGD</option><option>Adam</option><option>AdamW</option></select></div><div v-for="field in (['lr0','weight_decay','fliplr','degrees','hsv_v'] as const)" :key="field"><label class="label">{{field}}</label><input v-model.number="form[field]" type="number" step="any" class="input"/></div></div></details><div class="mt-5 max-w-xs"><label class="label">Recurso de cómputo</label><select v-model="form.device" class="input"><option value="server">Configuración del servidor</option><option value="cpu">CPU</option></select></div><div class="mt-5 flex flex-wrap items-center gap-5"><button class="btn" :disabled="busy||!form.version">Iniciar entrenamiento</button><p class="text-xs text-slate-400">La GPU/CPU se configura en el servidor. Solo un trabajo AI utiliza el recurso a la vez.</p></div></form>
<section class="card"><h2 class="mb-4 font-semibold">Experimentos registrados</h2><div v-if="runs.length" class="table-wrap"><table class="data-table"><thead><tr><th>Experimento</th><th>Estado</th><th>Progreso</th><th>Fecha</th><th></th></tr></thead><tbody><tr v-for="run in runs" :key="run.id"><td class="font-medium">{{run.architecture}}<span class="mt-1 block text-[10px] text-slate-400">{{run.id.slice(0,8)}}</span></td><td><StatusBadge :value="run.job.state"/></td><td><progress class="h-2 w-24 accent-emerald-700" :value="run.job.progress" max="100"></progress><span class="ml-2 text-xs">{{run.job.progress}}%</span></td><td class="text-xs">{{fmtDate(run.created_at)}}</td><td><button class="text-xs font-semibold text-emerald-700" @click="inspect(run)">Detalles</button></td></tr></tbody></table></div><EmptyState v-else title="Tu primer experimento" text="Congela una versión revisada del dataset para iniciar un entrenamiento."/></section>
<section v-if="detail" class="card mt-6"><h2 class="mb-3 font-semibold">Experimento {{detail.id.slice(0,8)}}</h2><p class="mb-4 text-xs text-slate-500">Intento {{detail.attempt}} · {{detail.job.config.device||'Configuración del servidor'}} · {{detail.duration_seconds!==null?formatMetric(detail.duration_seconds,1)+' segundos':'Duración pendiente'}}</p><p v-if="detail.job.error" class="mb-4 text-sm text-red-700">{{detail.job.error}}</p><p v-if="Object.keys(detail.metrics).length" class="mb-3 text-xs text-slate-500">Métricas de best.pt sobre validación. Test se reserva para la evaluación final.</p><div class="grid gap-3 sm:grid-cols-3"><div v-for="(value,key) in detail.metrics" :key="key" class="rounded-xl bg-slate-50 p-3"><p class="text-[10px] text-slate-500">{{key}}</p><p class="mt-2 font-semibold">{{formatMetric(value)}}</p></div></div><div v-if="detail.epochs_log.length" class="mt-5 max-h-80"><Line :data="{labels:detail.epochs_log.map((e:any)=>e.epoch),datasets:[{label:'mAP@0.5 validación',data:detail.epochs_log.map((e:any)=>e.metrics['metrics/mAP50(B)']??null),borderColor:'#153e2e',tension:.2}]}" :options="{responsive:true,maintainAspectRatio:false}"/></div><div v-if="detail.attempt>1" class="mt-4"><label class="label">Artefactos por intento</label><select v-model.number="attempt" class="input max-w-xs" @change="act(files)"><option v-for="n in detail.attempt" :key="n" :value="n">Intento {{n}}</option></select></div><div class="mt-4 flex flex-wrap gap-2"><button v-for="file in artifacts" :key="file" class="btn-secondary" @click="act(()=>download(`training-runs/${detail.id}/artifacts/?attempt=${attempt}&name=${encodeURIComponent(file)}`,file))">{{file}}</button></div><details class="mt-4 text-xs"><summary>Entorno y parámetros reproducibles</summary><pre class="mt-3 overflow-auto rounded-xl bg-slate-50 p-4">{{JSON.stringify({environment:detail.environment,config:detail.job.config},null,2)}}</pre></details></section></template>
